var s = msg['schema'];
if (s == null) { s = metadata['schema']; }
if (s == null) { s = '1'; }
metadata['schema'] = s;
return {msg: msg, metadata: metadata, msgType: msgType};

var mapping = {
  'aa': 'device.runtime.active_alarms',
  'at': 'device.runtime.alarm_transition',
  'atemp': 'device.sensor.ambient_temp_c',
  'bat': 'electrical.battery_level_pct',
  'ct': 'network.radio.connection_type',
  'dlms_f': 'dlms.session.failed',
  'dlms_ok': 'dlms.session.completed',
  'dlms_r': 'dlms.read.retrying',
  'dlms_st': 'dlms.session.started',
  'err': 'device.runtime.error_code',
  'fw': 'device.firmware.version',
  'ha': 'device.health.alert_active',
  'hr': 'device.nic.hw_rev',
  'hsc': 'device.health.score',
  'iccid': 'device.nic.sim.iccid',
  'imei': 'device.nic.imei',
  'imsi': 'device.nic.sim.imsi',
  'kwh': 'electrical.energy_kwh',
  'lcy': 'network.radio.latency_ms',
  'ln': 'device.location.longitude',
  'loss': 'network.radio.packet_loss_pct',
  'lt': 'device.location.latitude',
  'main': 'electrical.mains_status',
  'nid': 'device.id.nic_id',
  'oper': 'device.nic.sim.operator',
  'ota_p': 'lifecycle.ota.progress_pct',
  'ota_st': 'lifecycle.ota.state',
  'pip': 'device.nic.sim.ip',
  'rsrp': 'network.radio.rsrp_dbm',
  'rsrq': 'network.radio.rsrq_db',
  'rssi': 'network.radio.rssi_dbm',
  'rx': 'network.stats.bytes_received',
  'sid': 'device.id.som_id',
  'sm': 'device.id.som_model',
  'snr': 'network.radio.snr_db',
  'temp': 'device.sensor.internal_temp_c',
  'tx': 'network.stats.bytes_sent',
  'uid': 'device.id.uid',
  'upt': 'device.runtime.uptime_s',
  'v': 'electrical.voltage_v'
};
var out = {};
var partialFailures = {};
var hasFailures = false;
var ignored = {
  'aa': true,
  'at': true,
  'ev': true,
  'ha': true
};
for (key : msg.keySet()) {
  if (key != 'schema' && key != 'ts' && key != 'deviceId' && key != 'deviceName') {
    if (ignored[key] != true) {
      var canonical = mapping[key];
      if (canonical != null) {
        out[canonical] = msg[key];
      } else {
        partialFailures[key] = msg[key];
        hasFailures = true;
      }
    }
  }
}
var result = out;
result['candidateType'] = 'device_state';
if (hasFailures) {
  result['partialFailures'] = partialFailures;
  return {msg: result, metadata: metadata, msgType: 'FAILURE'};
}
return {msg: result, metadata: metadata, msgType: msgType};

var routes = {
  'alarm': 'tb.nic.candidate.alarm.v1',
  'device_state': 'tb.nic.candidate.device-state.v1',
  'lifecycle': 'tb.nic.candidate.lifecycle.v1',
  'ota': 'tb.nic.candidate.ota.v1'
};
var candidateType = msg['candidateType'];
if (candidateType == null) {
  var err = {'error': 'missing_candidate_type', 'candidateType': 'dlt'};
  return {msg: err, metadata: metadata, msgType: 'FAILURE'};
}
var topic = routes[candidateType];
if (topic == null) {
  var err2 = {'error': 'unknown_candidate_type', 'value': candidateType, 'candidateType': 'dlt'};
  return {msg: err2, metadata: metadata, msgType: 'FAILURE'};
}
metadata['kafkaTopic'] = topic;
return {msg: msg, metadata: metadata, msgType: msgType};
